function social(): void {global $config;echo '<div class="social-links">';foreach(['instagram'=>'<svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><rect x="3" y="3" width="18" height="18" rx="5"/><circle cx="12" cy="12" r="4"/><circle cx="17.5" cy="6.5" r=".7" fill="currentColor"/></svg>','facebook'=>'<svg viewBox="0 0 24 24" width="22" height="22" fill="currentColor" aria-hidden="true"><path d="M13.5 22v-9h3l.5-3.5h-3.5V7.25c0-1 .3-1.75 1.75-1.75H17V2.4c-.6-.1-1.65-.2-2.8-.2-2.8 0-4.7 1.7-4.7 4.8v2.5H6.5V13h3v9z"/></svg>','tiktok'=>'<svg viewBox="0 0 24 24" width="22" height="22" fill="currentColor" aria-hidden="true"><path d="M16.5 2c.3 2.5 1.7 4 4.2 4.2v3.3a8 8 0 0 1-4.2-1.3v7.1a6.4 6.4 0 1 1-5.5-6.4v3.5a3 3 0 1 0 2.1 2.9V2z"/></svg>'] as $key=>$icon)echo '<a class="social-icon '.$key.'" href="'.e($config['social'][$key]).'" aria-label="'.e(ucfirst($key)).'" target="_blank" rel="noopener noreferrer">'.$icon.'</a>';echo '</div>';}
function cards(array $ps): void {echo '<div class="product-grid" style="--product-columns:'.max(1,min(4,count($ps))).';--mobile-columns:'.max(1,min(2,count($ps))).'">';foreach($ps as $p){$save=$p['compare_price']?(float)$p['compare_price']-(float)$p['price']:0;echo '<article class="product-card" data-category="'.e($p['category']).'" data-name="'.e(strtolower($p['name'].' '.$p['description'])).'"><div class="product-photo"><button class="photo-button" data-quick="'.e($p['id']).'" aria-label="Quick view '.e($p['name']).'"><img src="'.e($p['image']).'" alt="'.e($p['name']).'" loading="lazy" width="640" height="640"></button>';if($save>0&&$p['in_stock'])echo '<span class="sale-badge">'.round($save/(float)$p['compare_price']*100).'% OFF</span>';echo '<button class="quick-view" data-quick="'.e($p['id']).'" aria-label="View '.e($p['name']).'">↗</button></div><div class="product-info"><p class="eyebrow">'.e($p['category'].' · '.$p['unit']).'</p><div class="product-title-row"><a href="/products/'.e($p['id']).'"><h3>'.e($p['name']).'</h3></a>';if(!$p['in_stock'])echo '<span class="stock-label">● Out of Stock</span>';echo '</div><div class="row between"><div><strong>'.money($p['price']).'</strong> ';if($save>0)echo '<del>'.money($p['compare_price']).'</del>';echo '</div><button class="add-button" data-add="'.e($p['id']).'" '.(!$p['in_stock']?'disabled':'').' aria-label="Add '.e($p['name']).' to basket">+</button></div>';if($save>0)echo '<small class="saving">Save '.money($save).'</small>';echo '</div></article>';}echo '</div>';}
function catalogPage(?string $category=null): void { $ps=products();if($category!==null)$ps=array_values(array_filter($ps,fn($p)=>$p['category']===$category));layout($category??'Our dairy collection',function()use($ps,$category){echo '<section class="section page-section"><div class="center-heading"><p class="eyebrow">THE WHITE GOLD COLLECTION</p><h1>'.e($category??'Our everyday goodness.').'</h1><p>Familiar flavours, thoughtfully prepared for your table.</p></div><div class="catalog-controls"><div class="filter-tabs"><button class="selected" data-filter="">All products</button>';foreach(categories() as $c)echo '<button data-filter="'.e($c).'">'.e($c).'</button>';echo '</div><label class="search-field">⌕ <input id="product-search" aria-label="Search products" placeholder="Find your favourite…"></label></div>';cards($ps);echo '<div class="empty" id="catalog-empty" '.($ps?'hidden':'').'><h3>Fresh goodness will be back soon.</h3><p>This collection is currently unavailable. Please check back soon or contact us for availability.</p><a href="/products" class="button outline">Explore all products</a></div></section>';});}
